local function trim(s)
    if not s then
        return ""
    end
    return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

function M.to_iso(country, raw)
    local name = trim(country)
    if name == "" then
        return ""
    end
    local mapped = COUNTRY_MAP[name]
    if mapped then
        return mapped
    end
    local upper = string.upper(name)
    if #upper == 2 or #upper == 3 then
        return upper
    end
    if name == "中国" and raw then
        if raw:find("香港", 1, true) then
            return "HK"
        end
        if raw:find("澳门", 1, true) then
            return "MO"
        end
        if raw:find("台湾", 1, true) then
            return "TW"
        end
    end
    return upper
end

return M
